UPDATE pms_sku_stock
SET lock_stock = lock_stock - #{quantity}
WHERE id = #{skuId}
  AND lock_stock >= #{quantity}

UPDATE ums_member
SET integration = COALESCE(integration, 0) + #{integration}
WHERE id = #{memberId}
